fn solve(n: i8) -> bool {
    // Extract each digit assuming n is a four-digit number (1000 to 9999).
    let d1 = n / 1000;          // thousands place
    let d2 = (n / 100) % 10;    // hundreds place
    let d3 = (n / 10) % 10;     // tens place
    let d4 = n % 10;            // ones place

    // Check if the first three digits are equal, or the last three digits are equal.
    (d1 == d2 && d2 == d3) || (d2 == d3 && d3 == d4)
}

